def answer_query(image, query):
    import numpy as np
    from typing import List

    def bool_to_yesno(bool_answer: bool) -> str:
        return "yes" if bool_answer else "no"

    image_patch = ImagePatch(image)
    groom_patches = image_patch.find(query)

    if not groom_patches:
        return bool_to_yesno(False)

    # If multiple instances of the query object are found, return the one with the largest area.
    groom_patches.sort(key=lambda patch: np.prod(patch.cropped_image.shape[:2]), reverse=True)
    largest_groom_patch = groom_patches[0]

    # Check if the object is a person.
    is_person = largest_groom_patch.exists("person")

    # If the object is a person, check if they have a beard.
    if is_person:
        return bool_to_yesno(largest_groom_patch.exists("beard"))
    else:
        return bool_to_yesno(largest_groom_patch.exists("groom"))

    return bool_to_yesno(False)


