    image_patch = ImagePatch(image)
    cow_patches = image_patch.find("cow")
    black_shirt_patches = image_patch.find("black shirt")

    if not cow_patches or not black_shirt_patches:
        return image_patch

    for cow in cow_patches:
        for shirt in black_shirt_patches:
            if cow.overlaps_with(shirt.left, shirt.lower, shirt.right, shirt.upper):
                return cow

    return cow_patches[0] if cow_patches else black_shirt_patches[0]

legacy_c5_yi.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    cows = image_patch.find("cow in a black shirt")
    if not cows:
        return image_patch
    return cows[0]

specguard.test:
def execute_test(image_patch):
    assert image_patch.exists("cow")
    assert image_patch.verify_property("cow", "black shirt")
